%[text] # Teaching Singular Value Decomposition with MATLAB Live Scripts
%[text] This live script is designed for educators who want one document that can act as lecture notes, a computational notebook, and a launch point for student experimentation.
%[text] It demonstrates rich text, symbolic equation display, inline variables, tables, tiled graphics, local helper functions, and exact symbolic calculations while exploring the singular value decomposition.
%[text:tableOfContents]{"heading":"Contents"}
%[text] - map live script features to teaching goals
%[text] - build geometric intuition for the SVD factorization
%[text] - compare low-rank approximations visually
%[text] - derive exact singular values with Symbolic Math Toolbox
%[text] - connect truncation error to the discarded singular values
%[text] - finish with classroom-ready teaching prompts \
format shortG
A = [3 1; 0 2];
[U,S,V] = svd(A);
hasSymbolic = exist('sym','class') == 8;
if hasSymbolic
    AExample = sym(A);
    UExample = sym(U);
    SigmaExample = sym(S);
    VExample = sym(V);
    factorizationRight = simplify(UExample*SigmaExample*VExample.');
    factorizationResidualSym = simplify(AExample - factorizationRight);
end
%%
%[text] ## Map Live Script Features to Teaching Goals
%[text] A live script can show the algebra, the MATLAB commands, and the computed evidence in one place, which makes it easier to pause and ask students to interpret what they see before moving on.
%[text] In this version, the main formulas are displayed with symbolic equations so that the classroom narrative stays inside MATLAB's computation environment instead of relying on typeset text.
%[text] This opening section models a useful classroom pattern: present one small matrix, compute the decomposition, and let the live script display the objects students will talk about.
capabilityTable = table(["Rich text and symbolic output"; "Inline computed values"; "Tables for discussion"; "Tiled graphics"; "Local helper functions"; "Symbolic exact math"], ["State the theory next to the code"; "Show residuals and singular values immediately"; "Organize matrices and comparisons for class discussion"; "Display several related views in one section"; "Reuse a compact block of code without leaving the lesson"; "Contrast exact formulas with floating-point approximations"], 'VariableNames', ["LiveScriptCapability","TeachingUse"]) %[output:6849f91c]
if hasSymbolic %[output:group:4d1cacbb]
    symbolicFactorizationTable = table(["A"; "U*Sigma*V.''"; "A-(U*Sigma*V.'')"], {AExample; factorizationRight; factorizationResidualSym}, 'VariableNames', ["Expression","Value"]) %[output:520048e4]
else
    disp("Symbolic Math Toolbox is not available on this machine, so symbolic equation display is skipped.")
end %[output:group:4d1cacbb]
factorizationTable = table(["A"; "U"; "Sigma"; "V"], {A; U; S; V}, 'VariableNames', ["Matrix","Value"]) %[output:9eac9c35]
stretchFactors = diag(S) %[output:1fd889d9]
reconstructionResidual = norm(A - U*S*V','fro') %[output:8ac1f2cc]
%%
%[text] ## Build Geometric Intuition for the SVD
%[text] A productive classroom story is that the transpose of the right singular vectors chooses the input directions, the diagonal singular-value matrix stretches along perpendicular axes, and the left singular vectors rotate or reflect the result into the output space.
%[text] Because this is a live script, the geometry can appear directly under the explanation instead of being split across slides and a separate coding environment.
if hasSymbolic %[output:group:49934e16]
    xSym = [sym('x_1'); sym('x_2')];
    xAligned = simplify(sym(V')*xSym);
    xScaled = simplify(sym(S)*xAligned);
    ySym = simplify(sym(U)*xScaled);
    symbolicStageTable = table(["Input x"; "Aligned V.''*x"; "Scaled Sigma*(V.''*x)"; "Output U*Sigma*(V.''*x)"], {xSym; xAligned; xScaled; ySym}, 'VariableNames', ["Stage","SymbolicVector"]) %[output:85663501]
end %[output:group:49934e16]
theta = linspace(0,2*pi,400);
unitCircle = [cos(theta); sin(theta)];
afterVt = V'*unitCircle;
afterSigma = S*afterVt;
afterU = U*afterSigma;
tiledlayout(2,2) %[output:90aa167b]
nexttile %[output:90aa167b]
plot(unitCircle(1,:),unitCircle(2,:),'k','LineWidth',1.5) %[output:90aa167b]
hold on %[output:90aa167b]
quiver(0,0,V(1,1),V(2,1),0,'LineWidth',1.5,'Color',[0.85 0.33 0.10]) %[output:90aa167b]
quiver(0,0,V(1,2),V(2,2),0,'LineWidth',1.5,'Color',[0 0.45 0.74]) %[output:90aa167b]
axis equal %[output:90aa167b]
grid on %[output:90aa167b]
title('Input circle and right singular directions') %[output:90aa167b]
xlabel('x_1') %[output:90aa167b]
ylabel('x_2') %[output:90aa167b]
nexttile %[output:90aa167b]
plot(afterVt(1,:),afterVt(2,:),'k','LineWidth',1.5) %[output:90aa167b]
hold on %[output:90aa167b]
quiver(0,0,1,0,0,'LineWidth',1.5,'Color',[0.85 0.33 0.10]) %[output:90aa167b]
quiver(0,0,0,1,0,'LineWidth',1.5,'Color',[0 0.45 0.74]) %[output:90aa167b]
axis equal %[output:90aa167b]
grid on %[output:90aa167b]
title('After V^T') %[output:90aa167b]
xlabel('z_1') %[output:90aa167b]
ylabel('z_2') %[output:90aa167b]
nexttile %[output:90aa167b]
plot(afterSigma(1,:),afterSigma(2,:),'k','LineWidth',1.5) %[output:90aa167b]
hold on %[output:90aa167b]
quiver(0,0,S(1,1),0,0,'LineWidth',1.5,'Color',[0.85 0.33 0.10]) %[output:90aa167b]
quiver(0,0,0,S(2,2),0,'LineWidth',1.5,'Color',[0 0.45 0.74]) %[output:90aa167b]
axis equal %[output:90aa167b]
grid on %[output:90aa167b]
title('After Sigma') %[output:90aa167b]
xlabel('w_1') %[output:90aa167b]
ylabel('w_2') %[output:90aa167b]
nexttile %[output:90aa167b]
plot(afterU(1,:),afterU(2,:),'k','LineWidth',1.5) %[output:90aa167b]
hold on %[output:90aa167b]
quiver(0,0,S(1,1)*U(1,1),S(1,1)*U(2,1),0,'LineWidth',1.5,'Color',[0.85 0.33 0.10]) %[output:90aa167b]
quiver(0,0,S(2,2)*U(1,2),S(2,2)*U(2,2),0,'LineWidth',1.5,'Color',[0 0.45 0.74]) %[output:90aa167b]
axis equal %[output:90aa167b]
grid on %[output:90aa167b]
title('After U') %[output:90aa167b]
xlabel('y_1') %[output:90aa167b]
ylabel('y_2') %[output:90aa167b]
%%
%[text] ## Compare Low-Rank Approximations Visually
%[text] Low-rank approximation is one of the fastest ways to show students that singular values are not just abstract numbers; they tell us what information survives when we compress a matrix.
%[text] This section uses a smooth test surface rather than an external data file so that the lesson is self-contained and easy for students to modify.
M = peaks(121);
[Um,Sm,Vm] = svd(M);
ranks = [1 5 15];
lowRankErrors = zeros(size(ranks));
lowRankEnergy = zeros(size(ranks));
singularValuesM = diag(Sm);
tiledlayout(2,3) %[output:66c31bff]
nexttile %[output:66c31bff]
imagesc(M) %[output:66c31bff]
axis image %[output:66c31bff]
title('Original matrix') %[output:66c31bff]
xlabel('column') %[output:66c31bff]
ylabel('row') %[output:66c31bff]
colorbar %[output:66c31bff]
for k = 1:numel(ranks)
    approximation = lowRankApprox(Um,Sm,Vm,ranks(k));
    lowRankErrors(k) = norm(M - approximation,'fro')/norm(M,'fro');
    lowRankEnergy(k) = sum(singularValuesM(1:ranks(k)).^2)/sum(singularValuesM.^2);
    nexttile %[output:66c31bff]
    imagesc(approximation)
    axis image
    title("Rank " + ranks(k) + " approximation")
    xlabel('column')
    ylabel('row')
    colorbar
end
nexttile %[output:66c31bff]
stem(singularValuesM(1:20),'filled','LineWidth',1.2) %[output:66c31bff]
grid on %[output:66c31bff]
title('Leading singular values') %[output:66c31bff]
xlabel('index') %[output:66c31bff]
ylabel('sigma_i') %[output:66c31bff]
nexttile %[output:66c31bff]
plot(ranks,lowRankErrors,'o-','LineWidth',1.5) %[output:66c31bff]
hold on %[output:66c31bff]
plot(ranks,lowRankEnergy,'s-','LineWidth',1.5) %[output:66c31bff]
grid on %[output:66c31bff]
title('Error and retained energy') %[output:66c31bff]
xlabel('chosen rank') %[output:66c31bff]
legend('relative Frobenius error','captured energy','Location','best') %[output:66c31bff]
lowRankSummary = table(ranks.', lowRankErrors.', lowRankEnergy.', 'VariableNames', ["Rank","RelativeFrobeniusError","CapturedEnergy"]) %[output:77d39e60]
%%
%[text] ## Derive Exact Singular Values with Symbolic Math Toolbox
%[text] A live script becomes especially effective for teaching when the same lesson can move from numerical evidence to exact algebra without changing documents.
%[text] Here a symbolic shear matrix is used so the class can see the exact Gram matrix and exact singular values directly in the output area.
if hasSymbolic %[output:group:572be1e4]
    syms t nonnegative
    Bsym = sym([1 t; 0 1]);
    GramSym = simplify(Bsym.'*Bsym) %[output:43d15d90]
    sigmaSym = flipud(simplify(sqrt(eig(GramSym)))) %[output:19181af0]
    sigmaAtTwo = vpa(subs(sigmaSym,t,2),6) %[output:870ff6de]
else
    disp("Symbolic Math Toolbox is not available on this machine, so this exact derivation is skipped.")
end %[output:group:572be1e4]
%%
%[text] ## Connect Truncation Error to the Discarded Singular Values
%[text] The symbolic view is also useful for explaining why the best rank-1 approximation of a diagonal matrix drops the smaller singular value and keeps the larger one.
%[text] The discarded symbolic matrix and the exact error formulas appear below as symbolic outputs rather than prose equations.
if hasSymbolic %[output:group:6afcdaf1]
    syms sigma1 sigma2 positive
    SigmaExact = diag([sigma1 sigma2]);
    SigmaRank1 = diag([sigma1 0]);
    discardedPart = SigmaExact - SigmaRank1 %[output:480912ea]
    exactFrobeniusError = simplify(sqrt(sum(discardedPart.^2,'all'))) %[output:5ef7212f]
    exactTwoNormError = sigma2 %[output:79fa259e]
    symbolicTruncationTable = table(["best rank-1 Frobenius error"; "best rank-1 2-norm error"], {exactFrobeniusError; exactTwoNormError}, 'VariableNames', ["Quantity","ExactResult"]) %[output:20d425a4]
else
    disp("Symbolic Math Toolbox is not available on this machine, so this exact truncation argument is skipped.")
end %[output:group:6afcdaf1]
%%
%[text] ## Classroom-Ready Teaching Prompts
%[text] The live editor supports a classroom rhythm that is difficult to reproduce with static slides because explanation, code, output, and student edits all stay in one place.
%[text] 1. Run the geometric section and ask students to predict which directions of the unit circle become the major and minor axes of the ellipse.
%[text] 2. In the low-rank section, change `ranks = [1 5 15]` and ask the class how much of the surface survives when only a few singular values are kept.
%[text] 3. In the symbolic shear section, substitute another value of `t` and compare the exact formulas with MATLAB's floating-point `svd` on the same numeric matrix.
%[text] 4. Replace the starter matrix `A` with a student-generated example and have the class narrate what the right singular vectors, singular values, and left singular vectors each do geometrically \
teachingTakeaways = table(["Reconstruction is numerically exact"; "Columns of U and V remain orthonormal"; "Discarded singular values quantify what is lost"], [reconstructionResidual; norm(U'*U - eye(size(U,2)),'fro'); lowRankErrors(1)], 'VariableNames', ["Takeaway","Evidence"]) %[output:26099102]
function approximation = lowRankApprox(U,S,V,r)
approximation = U(:,1:r)*S(1:r,1:r)*V(:,1:r)';
end

